using Microsoft.AspNetCore.OutputCaching;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddAuthentication().AddJwtBearer();
builder.Services.AddAuthorization();
builder.Services.AddOutputCache(options =>
{
    options.AddPolicy("Articles", policy => policy
        .Expire(TimeSpan.FromMinutes(10))
        .SetVaryByQuery("page"));
});
builder.Services.AddScoped<ArticleService>();
builder.Services.AddScoped<BookmarkService>();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();
app.UseOutputCache();

app.MapGet("/articles", (int? page, string? sort, ArticleService service, CancellationToken ct) =>
    service.ListAsync(page ?? 1, sort ?? "new", ct))
    .CacheOutput("Articles");

app.MapPut("/articles/{id:int}", async (int id, ArticleInput input, ArticleService service, CancellationToken ct) =>
{
    await service.UpdateAsync(id, input, ct);
    return Results.NoContent();
})
    .RequireAuthorization();

app.Run();

