builder.Services.AddOutputCache(options =>
{
    options.AddPolicy("Articles", policy => policy
        .Expire(TimeSpan.FromMinutes(10))
        .SetVaryByQuery("page", "sort")
        .Tag("articles"));
});

app.MapPut("/articles/{id:int}", async (int id, ArticleInput input, ArticleService service, IOutputCacheStore cache, CancellationToken ct) =>
{
    await service.UpdateAsync(id, input, ct);
    await cache.EvictByTagAsync("articles", ct);
    return Results.NoContent();
})
    .RequireAuthorization();

using System.Security.Claims;

options.AddPolicy("Bookmarks", policy => policy
    .Expire(TimeSpan.FromMinutes(1))
    .SetVaryByHeader("Authorization"));

app.MapGet("/me/bookmarks", (ClaimsPrincipal user, BookmarkService service, CancellationToken ct) =>
    service.ListAsync(user.FindFirstValue(ClaimTypes.NameIdentifier)!, ct))
    .CacheOutput("Bookmarks")
    .RequireAuthorization();
